var root=UnityEditor.PrefabUtility.LoadPrefabContents("Assets/Prefabs/Character.prefab");
try{
 var r=root.GetComponent<Character.Control.PaddleCharacterVisual>();var ids=new System.Collections.Generic.Dictionary<string,int>();var scales=new System.Collections.Generic.Dictionary<string,float>();float drift=0,scaleChange=0,elbowStep=0,error=0;UnityEngine.Vector3 l0=UnityEngine.Vector3.zero,r0=UnityEngine.Vector3.zero;
 foreach(float radius in new[]{.75f,1.35f,1.975f}){
  UnityEngine.Vector3 lastL=UnityEngine.Vector3.zero,lastR=UnityEngine.Vector3.zero;
  for(int i=0;i<=720;i++){
   var q=UnityEngine.Quaternion.Euler(0,0,i*.5f);r.tool.rotation=q;r.tool.position=r.body.position+q*new UnityEngine.Vector3(radius,.074f,0);r.Pose();
   var l=r.paddle.transform.InverseTransformPoint(r.LeftHand);var rr=r.paddle.transform.InverseTransformPoint(r.RightHand);if(ids.Count==0){l0=l;r0=rr;}else drift=UnityEngine.Mathf.Max(drift,UnityEngine.Vector3.Distance(l,l0),UnityEngine.Vector3.Distance(rr,r0));
   foreach(var sr in root.GetComponentsInChildren<UnityEngine.SpriteRenderer>())if(sr==r.leftUpper||sr==r.rightUpper||sr.name.StartsWith("Forearm segment ")||sr.name.StartsWith("Grip palm ")){
    if(!ids.ContainsKey(sr.name)){ids.Add(sr.name,sr.sprite.GetInstanceID());scales.Add(sr.name,sr.transform.localScale.x);}
    else if(ids[sr.name]!=sr.sprite.GetInstanceID())throw new System.Exception("Sprite frame switched");
    scaleChange=UnityEngine.Mathf.Max(scaleChange,UnityEngine.Mathf.Abs(sr.transform.localScale.x-scales[sr.name]));
   }
   if(i>0)elbowStep=UnityEngine.Mathf.Max(elbowStep,UnityEngine.Vector3.Distance(lastL,r.LeftElbow),UnityEngine.Vector3.Distance(lastR,r.RightElbow));lastL=r.LeftElbow;lastR=r.RightElbow;error=UnityEngine.Mathf.Max(error,r.HandError);
  }
 }
 if(!r.leftUpper.enabled||!r.rightUpper.enabled)throw new System.Exception("Continuous upper arm invisible");
 string log="2163 poses: no sprite/frame switches; constant scale delta="+scaleChange+" paddle-local target drift="+drift+" max elbow move per .5deg="+elbowStep+" wrist error="+error;
 System.IO.File.WriteAllText("scripts/player-continuous-arms-20261111/check.txt",log);UnityEngine.Debug.Log(log);
 if(drift>.00001f||scaleChange>.00001f||error>.001f||elbowStep>.1f)throw new System.Exception("Continuous follow regression");
}finally{UnityEditor.PrefabUtility.UnloadPrefabContents(root);}
